(()=>{'use strict';const node=document.getElementById('prison-data');if(!node)return;const rows=JSON.parse(node.textContent),$=id=>document.getElementById(id);let active=0,visible=rows.map((_,i)=>i);const sel=$('pr-page'),query=$('pr-search');
function filterImage(){$('pr-scan').style.width=$('pr-zoom').value+'%';$('pr-scan').style.filter='contrast('+$('pr-contrast').value+')'}
function show(i){active=i;const r=rows[i];sel.value=String(i);$('pr-id').textContent=r.id;$('pr-count').textContent=(i+1)+' di '+rows.length;$('pr-origin').textContent=r.pdf?'PDF fornito · scansione '+r.pdf:'Scansione recuperata dall’archivio';$('pr-scan').src=r.image;$('pr-scan').alt='Diario di Giovanni Martinelli · '+r.id+' · '+r.date;$('pr-scan').removeAttribute('width');$('pr-scan').removeAttribute('height');$('pr-original').href=r.image;$('pr-date').textContent=r.date;$('pr-state').textContent=r.status;$('pr-text').textContent=r.text;$('pr-notes').textContent=r.notes;$('pr-correction').href='mailto:pamazzi59@gmail.com?subject='+encodeURIComponent('Diario di prigionia - correzione '+r.id)+'&body='+encodeURIComponent('Scansione: '+r.id+'\nPosizione della riga:\nLettura proposta:\n');const p=visible.indexOf(i);$('pr-prev').disabled=p<=0;$('pr-next').disabled=p<0||p>=visible.length-1;$('pr-scanbox').scrollTop=0;$('pr-scanbox').scrollLeft=0;filterImage();if(history.replaceState)history.replaceState(null,'','#prigionia-'+r.id)}
function options(){const q=query.value.trim().toLocaleLowerCase('it');visible=rows.map((r,i)=>({r,i})).filter(({r})=>!q||(r.text+' '+r.date+' '+r.id).toLocaleLowerCase('it').includes(q)).map(({i})=>i);sel.replaceChildren();for(const i of visible){const o=document.createElement('option');o.value=String(i);o.textContent=rows[i].id+' · '+rows[i].date;sel.append(o)}$('pr-results').textContent=q?visible.length+' scansioni con corrispondenze nel testo disponibile':'';sel.disabled=!visible.length;if(visible.length)show(visible.includes(active)?active:visible[0]);else{$('pr-prev').disabled=true;$('pr-next').disabled=true}}
sel.addEventListener('change',()=>show(Number(sel.value)));$('pr-prev').addEventListener('click',()=>{const p=visible.indexOf(active);if(p>0)show(visible[p-1])});$('pr-next').addEventListener('click',()=>{const p=visible.indexOf(active);if(p>=0&&p<visible.length-1)show(visible[p+1])});query.addEventListener('input',options);$('pr-zoom').addEventListener('input',filterImage);$('pr-contrast').addEventListener('input',filterImage);$('pr-reset').addEventListener('click',()=>{$('pr-zoom').value='100';$('pr-contrast').value='1';filterImage()});let requested=decodeURIComponent(location.hash.replace('#prigionia-',''));const found=rows.findIndex(r=>r.id===requested);show(found>=0?found:0);
})();
